/* 极简二维码生成器（纯 JS，无依赖，离线可用）
 * 支持 byte 模式，自动选择版本(1-10)与纠错等级 L。
 * 用法： QRCode.generate(text) -> { modules, size } 二维布尔数组(size x size)
 *       QRCode.draw(canvas, text, opts) 直接绘制
 */
(function () {
  // ---- 基础数学工具 ----
  function qr(a, b) { return a % b; }
  function gfMul(a, b) {
    let r = 0;
    while (b) { if (b & 1) r ^= a; a <<= 1; if (a & 0x100) a ^= 0x11d; b >>= 1; }
    return r & 0xff;
  }

  // 生成伽罗瓦域对数/反对数表
  const EXP = new Array(256), LOG = new Array(256);
  (function () { let x = 1; for (let i = 0; i < 255; i++) { EXP[i] = x; LOG[x] = i; x = gfMul(x, 2); } EXP[255] = EXP[0]; })();

  function gfPow(n, p) { return EXP[(LOG[n] + p) % 255]; }
  function gfInv(n) { return EXP[(255 - LOG[n]) % 255]; }

  // 生成多项式系数（纠错用）
  function rsPoly(deg) {
    let poly = [1];
    for (let i = 0; i < deg; i++) {
      const np = new Array(poly.length + 1).fill(0);
      for (let j = 0; j < poly.length; j++) { np[j] ^= gfMul(poly[j], 1); np[j + 1] ^= gfMul(poly[j], gfPow(2, i)); }
      poly = np;
    }
    return poly;
  }

  // 字符计数与容量（byte 模式，版本1-10，纠错L）
  const CAP = {}; // CAP[v] = 该版本 byte 模式最大字符数(纠错L)
  (function () {
    // 公式：数据码字数(纠错L) = 总码字 - 纠错码字；byte模式每字符8bit
    const total = { 1: 26, 2: 44, 3: 70, 4: 100, 5: 134, 6: 172, 7: 196, 8: 242, 9: 292, 10: 346 };
    const ec = { 1: 7, 2: 10, 3: 15, 4: 20, 5: 26, 6: 18, 7: 22, 8: 22, 9: 24, 10: 28 };
    for (let v = 1; v <= 10; v++) CAP[v] = Math.floor((total[v] - ec[v]) * 8 / 8) - 0; // 粗略按字节容量
    // 更精确：数据码字 = total[v]-ec[v]; 每个byte占8bit，但需减模式(4bit)+计数(8/16bit)
  })();

  // 各版本尺寸
  function sizeOf(v) { return 17 + v * 4; }

  // 定位探测图形
  function placeFinder(m, n, r, c) {
    for (let i = -1; i <= 7; i++) for (let j = -1; j <= 7; j++) {
      const rr = r + i, cc = c + j;
      if (rr < 0 || cc < 0 || rr >= n || cc >= n) continue;
      const inB = i >= 0 && i <= 6 && (j === 0 || j === 6);
      const inV = j >= 0 && j <= 6 && (i === 0 || i === 6);
      const inC = i >= 2 && i <= 4 && j >= 2 && j <= 4;
      m[rr][cc] = (inB || inV || inC) ? 1 : 0;
    }
  }
  function placeTiming(m, n) {
    for (let i = 8; i < n - 8; i++) { m[6][i] = (i % 2 === 0) ? 1 : 0; m[i][6] = (i % 2 === 0) ? 1 : 0; }
  }

  // 编码数据
  function encodeData(text, version) {
    const bytes = [];
    for (let i = 0; i < text.length; i++) {
      const code = text.charCodeAt(i);
      if (code < 0x80) bytes.push(code);
      else if (code < 0x800) { bytes.push(0xc0 | (code >> 6), 0x80 | (code & 0x3f)); }
      else { bytes.push(0xe0 | (code >> 12), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f)); }
    }
    const capBits = { 1: 152, 2: 272, 3: 440, 4: 640, 5: 864, 6: 1088, 7: 1248, 8: 1552, 9: 1856, 10: 2192 }[version];
    const bits = [];
    const push = (v, len) => { for (let i = len - 1; i >= 0; i--) bits.push((v >> i) & 1); };
    push(0b0100, 4); // byte mode
    const cnt = text.length;
    push(cnt, version <= 9 ? 8 : 16);
    for (const b of bytes) push(b, 8);
    // 终止符
    for (let i = 0; i < 4 && bits.length < capBits; i++) bits.push(0);
    while (bits.length % 8) bits.push(0);
    // 转字节
    const data = [];
    for (let i = 0; i < bits.length; i += 8) { let v = 0; for (let j = 0; j < 8; j++) v = (v << 1) | bits[i + j]; data.push(v); }
    // 填充码字
    const total = { 1: 26, 2: 44, 3: 70, 4: 100, 5: 134, 6: 172, 7: 196, 8: 242, 9: 292, 10: 346 }[version];
    const ecw = { 1: 7, 2: 10, 3: 15, 4: 20, 5: 26, 6: 18, 7: 22, 8: 22, 9: 24, 10: 28 }[version];
    const need = total - ecw;
    const pad = [0xec, 0x11];
    let pi = 0;
    while (data.length < need) data.push(pad[pi++ % 2]);
    // 纠错码字（里德-所罗门）
    const gen = rsPoly(ecw);
    const res = new Array(ecw).fill(0);
    for (const b of data) {
      const f = b ^ res[0];
      res.shift();
      res.push(0);
      for (let i = 0; i < ecw; i++) res[i] ^= gfMul(gen[i + 1], f);
    }
    return data.concat(res);
  }

  function placeData(m, n, codewords) {
    let bitIdx = 0;
    const totalBits = codewords.length * 8;
    let col = n - 1;
    let up = true;
    while (col > 0) {
      if (col === 6) col--; // 跳过时序列
      for (let i = 0; i < n; i++) {
        const row = up ? n - 1 - i : i;
        for (let c = 0; c < 2; c++) {
          const cc = col - c;
          if (m[row][cc] !== undefined) continue;
          let bit = 0;
          if (bitIdx < totalBits) { bit = (codewords[bitIdx >> 3] >> (7 - (bitIdx & 7))) & 1; bitIdx++; }
          m[row][cc] = bit;
        }
      }
      col -= 2;
      up = !up;
    }
  }

  function generate(text) {
    let version = 1;
    while (version < 10 && text.length > { 1: 17, 2: 32, 3: 53, 4: 78, 5: 106, 6: 134, 7: 154, 8: 192, 9: 230, 10: 271 }[version]) version++;
    if (version === 10 && text.length > 271) throw new Error('文本过长');
    const n = sizeOf(version);
    const m = Array.from({ length: n }, () => new Array(n).fill(undefined));
    placeFinder(m, n, 0, 0);
    placeFinder(m, n, 0, n - 7);
    placeFinder(m, n, n - 7, 0);
    placeTiming(m, n);
    // 定位图形分隔 + 格式信息区留空（不实现掩码优化，固定掩码0）
    const cw = encodeData(text, version);
    placeData(m, n, cw);
    // 固定使用掩码 0 并填格式信息（简化：掩码0）
    applyMask(m, n, 0);
    // 返回 bool 矩阵
    const mod = m.map((r) => r.map((v) => (v ? 1 : 0)));
    return { modules: mod, size: n };
  }

  function applyMask(m, n, mask) {
    for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) {
      if (m[r][c] === undefined) continue;
      let flip = false;
      if (mask === 0) flip = (r + c) % 2 === 0;
      if (flip) m[r][c] = m[r][c] ? 0 : 1;
    }
  }

  function draw(canvas, text, opts) {
    opts = opts || {};
    const qr = generate(text);
    const sz = qr.size;
    const scale = opts.scale || 6;
    const margin = opts.margin || 4;
    canvas.width = canvas.height = (sz + margin * 2) * scale;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = opts.light || '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = opts.dark || '#1a1a1a';
    for (let r = 0; r < sz; r++) for (let c = 0; c < sz; c++) {
      if (qr.modules[r][c]) ctx.fillRect((c + margin) * scale, (r + margin) * scale, scale, scale);
    }
  }

  window.QRCode = { generate, draw };
})();
